#define k_button_mypos_anim_pressed				     ( MENU_A_MENU_DIFFICULTY_PRESSED )
#define k_button_mypos_anim_blink					 ( MENU_A_MENU_DIFFICULTY_BLINK )
#define k_button_mypos_anim_disabled				 ( MENU_A_MENU_DIFFICULTY_BLINK )
